  const [sovBarTooltip, setSovBarTooltip] = useState(null);
  const sovBarRefs = useRef({});
  const sovScrollRef = useRef(null);

  useEffect(() => {
    if (!sovSelected) return;
    const container = sovScrollRef.current;
    const item = sovBarRefs.current[sovSelected.app];
    if (!container || !item) return;
    const containerRect = container.getBoundingClientRect();
    const itemRect = item.getBoundingClientRect();
    const itemTopRelative = itemRect.top - containerRect.top + container.scrollTop;
    const targetTop = itemTopRelative - (container.clientHeight / 2) + (item.clientHeight / 2);
    container.scrollTo({ top: Math.max(0, targetTop), behavior: "smooth" });
  }, [sovSelected]);

  const TABS = [
    { key: "summary",     label: "Executive Summary"   },
    { key: "audience",    label: "Audience Definition"  },
    { key: "platform",    label: "Platform Analysis"    },
    { key: "sov",         label: "Competitive SOV"      },
    { key: "rankings",    label: "Detailed Rankings"    },
    { key: "methodology", label: "Methodology"          },
  ];

  const data = useMemo(() =>
    RAW_DATA.map(d => {
      const sov = SOV_DATA.find(s => s.app === d.app);
      return {
        ...d,
        allstate_sov: sov ? sov.allstate : 0,
        priority: d.intender_pct * d.median_index / 100,
      };
    }),
  []);

  const sovMerged = useMemo(() => SOV_DATA.map(s => {
    const raw = RAW_DATA.find(r => r.app === s.app);
    const tier = raw ? getTier(raw) : "deprioritize";
    const intender_pct = raw ? raw.intender_pct : 0;
    const median_index = raw ? raw.median_index : 100;
    const priority = intender_pct * median_index / 100;
    return { ...s, tier, intender_pct, median_index, priority };
  }), []);

  const medianAllateSov = useMemo(() => {
    const sorted = [...sovMerged].map(d => d.allstate).sort((a,b) => a-b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 === 0 ? (sorted[mid-1]+sorted[mid])/2 : sorted[mid];
  }, [sovMerged]);

  const medianHHI = useMemo(() => {
    const sorted = [...sovMerged].map(d => d.hhi).sort((a,b) => a-b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 === 0 ? (sorted[mid-1]+sorted[mid])/2 : sorted[mid];
  }, [sovMerged]);

  const tierGroups = useMemo(() => {
    const groups = { anchor: [], efficiency: [], scale: [], deprioritize: [] };
    data.forEach(d => groups[getTier(d)].push(d.app));
    return groups;
  }, [data]);

  const sorted = useMemo(() => {
    const arr = [...data];
    arr.sort((a, b) => {
      const av = sortCol === "app" ? a.app : a[sortCol];
      const bv = sortCol === "app" ? b.app : b[sortCol];
      if (sortCol === "app") return sortDir === "asc" ? av.localeCompare(bv) : bv.localeCompare(av);
      return sortDir === "asc" ? av - bv : bv - av;
    });
    return arr;
  }, [data, sortCol, sortDir]);

  const toggleSort = (col) => {
    if (sortCol === col) setSortDir(d => d === "asc" ? "desc" : "asc");
    else { setSortCol(col); setSortDir("desc"); }
  };

